#!/bin/bash
#

# Generated by CHARMM-GUI (http://www.charmm-gui.org) v3.7
#
# This folder contains a pre-optimized PDB structure and OpenMM inputs.
# All input files were optimized for OpenMM v6.2 or above, so lower version of OpenMM can cause some errors.
# You can get the latest development version of OpenMM at the git repository:
# https://github.com/pandegroup/openmm

# INPUTS
# 1 --> gpus to run the simulations (default: 0)
# --faster (anywhere) --> NVIDIA cuPotential engine (~2.5x faster; needs the
#                         openmm_faster environment, see Installation_readme.md)
#
# Examples:  bash utils/run.sh 0            classic OpenMM engine
#            bash utils/run.sh 0 --faster   cuPotential engine

GPU=0; FASTER=""; ENGINE=classic
for arg in "$@"; do
    case "$arg" in
        --faster) FASTER="--faster"; ENGINE=faster ;;
        -*) echo "ERROR: unknown option $arg (only --faster)"; exit 1 ;;
        *) GPU="$arg" ;;
    esac
done
echo "Engine: $ENGINE  GPU: $GPU"
if [ -n "$FASTER" ] && ! python -c "import nv_openmm_plugin" 2>/dev/null; then
    echo "ERROR: --faster needs the cuPotential plugin (nv_openmm_plugin), not found in this environment."
    echo "       conda activate openmm_faster, or install it with utils/install_faster.sh"
    exit 1
fi
# A .chk checkpoint holds integrator state and only loads into the same engine;
# the XML .rst states are portable. Remember which engine wrote the last chunk.
PREV_ENGINE=$(cat run_engine.txt 2>/dev/null || echo "$ENGINE")

# Input file prefix
init=step3_input

# Number of equilibration steps = number of step4.*_equilibration.inp files
n_eq=$(ls -1 step4.*_equilibration.inp | wc -l)

# Check if any step4*.rst files exist
if ls step4*.rst &> /dev/null; then
    # If files exist, find the highest numbered file
    cnt=$(ls -1 step4*.rst | sort -V | tail -1 | cut -d '_' -f1 | cut -d '.' -f2)
    cnt=$(( $cnt + 1 ))
else
    # If no files exist, set cnt to 1
    cnt=1
fi

echo "Equilibration cnt is: $cnt (of $n_eq)"

while [ ${cnt} -le ${n_eq} ]
do
	pcnt=$(( $cnt - 1 ))
	istep=step4.${cnt}_equilibration
	pstep=step4.${pcnt}_equilibration

	if [ $cnt == 1 ]; then
		input_param="-ff amber -p ${init}.parm7 -c ${init}.rst7"
	else
		input_param="-ff amber -p ${init}.parm7 -c ${init}.rst7 -irst ${pstep}.rst"
	fi
	python -u utils/openmm_run.py -i ${istep}.inp ${input_param} -orst ${istep}.rst -ochk ${istep}.chk -odcd ${istep}.dcd -gpu ${GPU} ${FASTER} > ${istep}.out
	if [ ! -s ${istep}.rst ]; then
		echo "ERROR: ${istep}.rst was not created. See ${istep}.out" ; exit 1
	fi

    	cnt=$(( $cnt + 1 ))
done


######################################### PRODUCTION PIPELINE #########################################

prod_prefix=step5_production
prod_step=step5
last_eq=step4.${n_eq}_equilibration

# Extract nstout and dt from the inp file of production
inp_file=${prod_prefix}.inp
dt=$(awk '/^dt[[:space:]]*=/{print $3}' "$inp_file")
nstout=$(awk '/^nstout[[:space:]]*=/{print $3}' "$inp_file")
target_ns=$(awk '/^Target_ns[[:space:]]*=/{print $3}' "$inp_file")
# Sanity check
if [[ -z "$dt" || -z "$nstout" ]]; then
    echo "Error: Failed to extract dt or nstout from $inp_file"
    exit 1
fi

# Compute how many steps correspond to 1 ns
steps_per_ns=$(echo "1000 / $dt" | bc)                # 1000 ps / 0.002 ps = 500000 steps/ns
total_steps=$(printf "%.0f" $(echo "$target_ns * $steps_per_ns" | bc)) # Total steps to run (integer)

# Count reporter lines in all step5_*.out files (1 line per nstout steps; log lines start with '[' or '#')
count_steps () {
    local n=$(cat ${prod_step}_*.out 2>/dev/null | grep -c '^[0-9]')
    echo $(( n * nstout ))
}
completed_steps=$(count_steps)


# Check if any step5*.chk files exist
if ls $prod_step*.chk &> /dev/null; then
    # If files exist, find the highest numbered file
    cnt=$(ls -1 $prod_step*.chk | sort -V | tail -1 | cut -d '_' -f2 | cut -d '.' -f1)
    cnt=$(( $cnt + 1 ))
else
    # If no files exist, set cnt to 1
    cnt=1
fi
echo "Starting at run count $cnt, completed_steps: $completed_steps / $total_steps"

# The OpenMM check point file (.chk) cannot be used in a different machine environment.
# So please make sure if you are using the same GPU and CUDA version of machine while doing additional

# Run until you've simulated the desired number of steps
while [ "$completed_steps" -lt "$total_steps" ]
do
    pcnt=$(($cnt - 1))
    istep=${prod_step}_${cnt}
    pstep=${prod_step}_${pcnt}

    # First chunk starts from the equilibration .rst (portable XML state): a .chk may only be
    # loaded into an identical system, and production differs (no restraints, maybe HMR).
    if [ $cnt == 1 ];then
       pstep=${last_eq}
       input_param="-ff amber -p ${init}.parm7 -c ${init}.rst7 -irst ${pstep}.rst"
    elif [ -f ${pstep}.chk ] && [ "$PREV_ENGINE" = "$ENGINE" ]; then
        input_param="-ff amber -p ${init}.parm7 -c ${init}.rst7 -ichk ${pstep}.chk"
    elif [ -f ${pstep}.rst ]; then
        input_param="-ff amber -p ${init}.parm7 -c ${init}.rst7 -irst ${pstep}.rst"
    else
        echo "ERROR: Neither ${pstep}.chk nor ${pstep}.rst found." ; exit 1
    fi

    echo ">>> Running $istep..."
    if [ "$PREV_ENGINE" != "$ENGINE" ] && [ $cnt -gt 1 ]; then
        echo ">>> Engine changed ($PREV_ENGINE -> $ENGINE): restarting from ${pstep}.rst, not the .chk"
    fi
    python -u utils/openmm_run.py -i ${prod_prefix}.inp ${input_param} -orst ${istep}.rst -ochk ${istep}.chk -odcd ${istep}.dcd -gpu ${GPU} ${FASTER} > ${istep}.out
    echo "$ENGINE" > run_engine.txt; PREV_ENGINE=$ENGINE

    echo ">>> Checking if ${istep}.dcd file exists"
    if [ ! -s ${istep}.dcd ]; then
    	echo "ERROR: ${istep}.dcd was not created or is empty. Exiting."
    	exit 1
    fi

    # Update counters after the run
    cnt=$((cnt + 1))
    completed_steps=$(count_steps)
done
